CREATE OR REPLACE FUNCTION public.accept_company_access_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_email text;
  v_hash text;
  v_inv public.company_access_invitations%rowtype;
  v_existing_role text;
begin
  if v_uid is null then raise exception 'Authentication required'; end if;
  if p_token is null or char_length(p_token) < 32 then raise exception 'Invalid invitation token'; end if;

  select lower(email) into v_email from auth.users where id=v_uid;
  if v_email is null then raise exception 'Authenticated email required'; end if;

  v_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');
  select * into v_inv from public.company_access_invitations
   where token_hash=v_hash and status='pending'
   for update;
  if not found then raise exception 'Invitation not found or no longer pending'; end if;

  if v_inv.expires_at <= now() then
    update public.company_access_invitations
       set status='expired', updated_at=now()
     where id=v_inv.id;
    return jsonb_build_object('status','expired');
  end if;

  if lower(v_inv.email) <> v_email then raise exception 'Invitation email does not match authenticated user'; end if;

  select role into v_existing_role
    from public.company_memberships
   where company_id=v_inv.company_id and user_id=v_uid;

  if v_existing_role is not null then
    if v_existing_role='owner' then raise exception 'Company owner cannot accept delegated invitation'; end if;
    raise exception 'User already has access to this company';
  end if;

  insert into public.company_memberships(company_id,user_id,role,verification_status,verification_method,verified_at)
  values(v_inv.company_id,v_uid,v_inv.role,'verified','email_invitation',now());

  update public.company_access_invitations
     set status='accepted', accepted_by=v_uid, accepted_at=now(), updated_at=now()
   where id=v_inv.id;

  return jsonb_build_object('company_id',v_inv.company_id,'role',v_inv.role,'status','accepted');
end $function$

CREATE OR REPLACE FUNCTION public.accept_my_company_invitation(p_invitation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_email text; v_inv public.company_access_invitations%rowtype;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 select lower(email) into v_email from auth.users where id=v_uid;
 if v_email is null or btrim(v_email)='' then raise exception using errcode='42501',message='Authenticated email required'; end if;
 select * into v_inv from public.company_access_invitations where id=p_invitation_id and status='pending' for update;
 if not found then raise exception 'Invitation not found or no longer pending'; end if;
 if lower(v_inv.email) IS DISTINCT FROM v_email then raise exception 'Invitation email does not match authenticated user'; end if;
 if v_inv.expires_at<=now() then update public.company_access_invitations set status='expired',updated_at=now() where id=v_inv.id; return jsonb_build_object('status','expired'); end if;
 if exists(select 1 from public.company_memberships where company_id=v_inv.company_id and user_id=v_uid) then raise exception 'User already has access to this company'; end if;
 insert into public.company_memberships(company_id,user_id,role,verification_status,verification_method,verified_at) values(v_inv.company_id,v_uid,v_inv.role,'verified','account_invitation',now());
 update public.company_access_invitations set status='accepted',accepted_by=v_uid,accepted_at=now(),updated_at=now() where id=v_inv.id;
 return jsonb_build_object('status','accepted','company_id',v_inv.company_id,'role',v_inv.role);
end $function$

CREATE OR REPLACE FUNCTION public.can_upload_specialist_object(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT public.can_manage_specialist_object(p_name) THEN RETURN false; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||split_part(p_name,'/',1),0));
 -- Recheck ownership after waiting; coordinate with draft deletion and pin its row.
 PERFORM 1 FROM public.specialist_profiles WHERE id=CASE WHEN split_part(p_name,'/',1) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN split_part(p_name,'/',1)::uuid END AND owner_user_id=auth.uid() AND profile_status='draft' FOR KEY SHARE;
 IF NOT FOUND THEN RETURN false; END IF;
 RETURN (SELECT count(*) FROM storage.objects WHERE bucket_id='specialist-media' AND split_part(name,'/',1)=split_part(p_name,'/',1))<20;
END $function$

CREATE OR REPLACE FUNCTION public.confirm_my_specialist_erasure(p_specialist_id uuid, p_confirmation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_erasure_confirmations;
BEGIN
 IF auth.uid() IS NULL OR p_confirmation_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() AND profile_status IN ('draft','erasing') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 INSERT INTO public.specialist_erasure_confirmations(id,profile_id,owner_user_id) VALUES(p_confirmation_id,p_specialist_id,auth.uid()) ON CONFLICT(id) DO NOTHING;
 SELECT * INTO r FROM public.specialist_erasure_confirmations WHERE id=p_confirmation_id AND profile_id=p_specialist_id AND owner_user_id=auth.uid() AND expires_at>now();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Confirmation unavailable or expired'; END IF;
 UPDATE public.specialist_profiles SET profile_status='erasing' WHERE id=p_specialist_id;
 INSERT INTO public.specialist_publication_state(specialist_id,state,published_revision_id) VALUES(p_specialist_id,'erasing',NULL)
 ON CONFLICT(specialist_id) DO UPDATE SET state='erasing',published_revision_id=NULL;
 RETURN jsonb_build_object('confirmation_id',r.id,'expires_at',r.expires_at);
END $function$

CREATE OR REPLACE FUNCTION public.create_my_company(p_name text, p_slug text, p_website text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_company_id uuid;
  v_membership_id uuid;
  v_existing_id uuid;
  v_existing_slug text;
  v_name text := btrim(coalesce(p_name,''));
  v_base_slug text := lower(btrim(coalesce(p_slug,'')));
  v_slug text;
  v_suffix integer := 0;
  v_website text := nullif(btrim(coalesce(p_website,'')),'');
  v_website_host text;
  v_default_website boolean;
  v_constraint text;
  v_phone text := nullif(btrim(coalesce(p_phone,'')),'');
  v_city text := nullif(btrim(coalesce(p_city,'')),'');
  v_email text := nullif(lower(btrim(coalesce(p_email,''))),'');
begin
  if v_user_id is null then
    raise exception using errcode='42501', message='Authentication required';
  end if;
  if v_name='' or char_length(v_name)>200 then
    raise exception using errcode='22023', message='Company name must contain 1-200 characters';
  end if;
  if v_base_slug !~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$' then
    raise exception using errcode='22023', message='Invalid company slug';
  end if;
  if v_base_slug in ('www','api','admin','test','test2','account','login','profiles','specialists') then
    raise exception using errcode='22023', message='Reserved company slug';
  end if;

  v_default_website := v_website IS NULL OR v_website IN (
    'https://' || v_base_slug || '.xn--b1ajuq0c.com/',
    'https://' || v_base_slug || '.отзыв.com/');
  if NOT v_default_website then
    v_website_host := lower(regexp_replace(regexp_replace(v_website,'^https?://','','i'),'/.*$',''));
    v_website_host := regexp_replace(v_website_host,'^www\.','','i');
  end if;

  select c.id,c.slug into v_existing_id,v_existing_slug
  from public.companies c
  where c.status <> 'archived'
    and (
      (v_website_host is not null and
       regexp_replace(lower(regexp_replace(regexp_replace(coalesce(c.website,''),'^https?://','','i'),'/.*$','')),'^www\.','','i') = v_website_host)
      or
      (lower(btrim(c.name))=lower(v_name)
       and lower(btrim(coalesce(c.city,'')))=lower(btrim(coalesce(v_city,'')))
       and coalesce(v_city,'')<>'')
    )
  order by c.created_at
  limit 1;

  if v_existing_id is not null then
    if exists(select 1 from public.company_memberships m where m.company_id=v_existing_id and m.user_id=v_user_id and m.verification_status<>'revoked') then
      raise exception using errcode='23505', message='Company already exists in your account';
    end if;
    raise exception using errcode='23505', message='Company already exists';
  end if;

  loop
    v_slug := case when v_suffix=0 then v_base_slug else rtrim(left(v_base_slug, 63 - 1 - char_length((v_suffix+1)::text)), '-')||'-'||(v_suffix+1)::text end;
    if char_length(v_slug)>63 OR v_suffix > 100 then
      raise exception using errcode='22023', message='No available company slug';
    end if;
    IF v_default_website THEN
      v_website := 'https://' || v_slug || '.xn--b1ajuq0c.com/';
    END IF;
    begin
      insert into public.companies(slug,name,website,phone,city,email,status,profile_status)
      values(v_slug,v_name,v_website,v_phone,v_city,v_email,'active','ready')
      returning id into v_company_id;
      exit;
    exception when unique_violation then
      GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
      IF v_constraint NOT IN ('companies_slug_key','profile_slug_registry_pkey') THEN RAISE; END IF;
      v_suffix:=v_suffix+1;
    end;
  end loop;

  insert into public.company_memberships(company_id,user_id,role,verification_status,verification_method,verified_at)
  values(v_company_id,v_user_id,'owner','verified','creator',now())
  returning id into v_membership_id;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(v_company_id,v_user_id,'company_created','company',v_company_id::text,
    jsonb_build_object('slug',v_slug,'role','owner','verification_method','creator'));

  return jsonb_build_object(
    'company',jsonb_build_object('id',v_company_id,'slug',v_slug,'public_url','https://'||v_slug||'.xn--b1ajuq0c.com/','name',v_name,'website',v_website,'phone',v_phone,'city',v_city,'email',v_email,'status','active','profile_status','ready'),
    'membership',jsonb_build_object('id',v_membership_id,'role','owner','verification_status','verified')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_company_location(p_company_id uuid, p_name text, p_address text, p_city text, p_phone text DEFAULT NULL::text, p_hours jsonb DEFAULT '{}'::jsonb, p_official_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_id uuid;
  v_role text;
begin
  if v_user is null then
    raise exception 'authentication_required' using errcode='42501';
  end if;

  select role into v_role
  from public.company_memberships
  where company_id = p_company_id
    and user_id = v_user
    and verification_status = 'verified'
    and role in ('owner','admin')
  limit 1;

  if v_role is null then
    raise exception 'verified_owner_or_admin_required' using errcode='42501';
  end if;

  if nullif(trim(coalesce(p_name,'')),'') is null
     or nullif(trim(coalesce(p_address,'')),'') is null
     or nullif(trim(coalesce(p_city,'')),'') is null then
    raise exception 'name_address_city_required' using errcode='22023';
  end if;

  insert into public.company_locations(
    company_id, name, relationship_type, canonical_address, city,
    phone, hours, official_url, source_url, status, verified_at
  )
  values(
    p_company_id, trim(p_name), 'owned', trim(p_address), trim(p_city),
    nullif(trim(coalesce(p_phone,'')),''),
    coalesce(p_hours,'{}'::jsonb),
    nullif(trim(coalesce(p_official_url,'')),''),
    'owner-submitted', 'published', now()
  )
  returning id into v_id;

  insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
  values(
    p_company_id, v_user, 'company_location.created', 'location', v_id,
    jsonb_build_object('role',v_role)
  );

  return jsonb_build_object('id',v_id,'company_id',p_company_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_company_service(p_company_id uuid, p_name text, p_category text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_official_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_user uuid:=auth.uid(); v_id uuid; v_role text;
begin
 if v_user is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select role into v_role from public.company_memberships where company_id=p_company_id and user_id=v_user and verification_status='verified' and role in ('owner','admin') limit 1;
 if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;
 if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'service_name_required' using errcode='22023'; end if;
 insert into public.company_services(company_id,name,category,description,official_url,source_url,status,verified_at)
 values(p_company_id,trim(p_name),nullif(trim(coalesce(p_category,'')),''),nullif(trim(coalesce(p_description,'')),''),nullif(trim(coalesce(p_official_url,'')),''),'owner-submitted','published',now()) returning id into v_id;
 insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata) values(p_company_id,v_user,'company_service.created','service',v_id,jsonb_build_object('role',v_role));
 return jsonb_build_object('id',v_id,'company_id',p_company_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_specialist_draft(p_display_name text, p_slug text, p_profession text DEFAULT NULL::text, p_specialization text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_name text := btrim(coalesce(p_display_name,''));
  v_slug text := lower(btrim(coalesce(p_slug,'')));
  v_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Authentication required';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('specialist-drafts:'||v_user_id::text,0));
  IF (SELECT count(*) FROM public.specialist_profiles WHERE owner_user_id=v_user_id)>=10 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='Draft limit reached'; END IF;
  IF char_length(v_name) NOT BETWEEN 2 AND 150 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid specialist name';
  END IF;
  IF char_length(btrim(coalesce(p_profession,''))) NOT BETWEEN 1 AND 120 OR char_length(coalesce(p_specialization,'')) > 160 OR char_length(coalesce(p_city,'')) > 120 OR char_length(coalesce(p_description,'')) > 2000 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Specialist field too long';
  END IF;
  IF v_slug !~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$'
     OR v_slug ~ '^xn--'
     OR v_slug IN ('www','api','admin','test','test2','account','login','profiles','specialists')
  THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid or reserved slug';
  END IF;
  INSERT INTO public.specialist_profiles(owner_user_id,slug,display_name,profession,specialization,city,description)
  VALUES (v_user_id,v_slug,v_name,
          nullif(btrim(coalesce(p_profession,'')),''),
          nullif(btrim(coalesce(p_specialization,'')),''),
          nullif(btrim(coalesce(p_city,'')),''),nullif(btrim(coalesce(p_description,'')),''))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id',v_id,'slug',v_slug,'profile_status','draft');
END
$function$

CREATE OR REPLACE FUNCTION public.decline_my_company_invitation(p_invitation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_email text;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 select lower(email) into v_email from auth.users where id=v_uid;
 update public.company_access_invitations set status='revoked',updated_at=now()
 where id=p_invitation_id and status='pending' and lower(email)=v_email;
 return found;
end $function$

CREATE OR REPLACE FUNCTION public.delete_my_specialist_draft(p_specialist_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Authentication required'; END IF;
 IF NOT EXISTS(SELECT FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() AND profile_status IN ('draft','erasing')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() AND profile_status IN ('draft','erasing') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 IF EXISTS(SELECT FROM public.specialist_upload_reservations WHERE specialist_id=p_specialist_id AND state<>'deleted') OR EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND split_part(name,'/',1)=p_specialist_id::text) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Remove specialist files before deleting draft'; END IF;
 DELETE FROM public.specialist_profiles WHERE id=p_specialist_id;
 RETURN jsonb_build_object('id',p_specialist_id,'deleted',true);
END $function$

CREATE OR REPLACE FUNCTION public.delete_my_specialist_service(p_specialist_id uuid, p_service_id uuid, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Authentication required'; END IF;
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF; DELETE FROM public.specialist_services WHERE id=p_service_id AND specialist_id=p_specialist_id AND version=p_version; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Reload service'; END IF; RETURN jsonb_build_object('id',p_service_id); END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_companies()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'company', jsonb_build_object(
        'id', c.id, 'slug', c.slug,
        'public_url', 'https://' || c.slug || '.xn--b1ajuq0c.com/',
        'name', c.name, 'description', c.description, 'city', c.city,
        'website', c.website, 'phone', c.phone, 'email', c.email,
        'status', c.status, 'profile_status', c.profile_status
      ),
      'membership', jsonb_build_object(
        'id', m.id, 'role', m.role, 'verification_status', m.verification_status
      )
    ) order by c.created_at desc)
    from public.company_memberships m
    join public.companies c on c.id = m.company_id
    where m.user_id = v_user_id
      and m.verification_status = 'verified'
  ), '[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_company_access(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception using errcode='42501',message='Authentication required'; end if;
 if not exists(select 1 from public.company_memberships where company_id=p_company_id and user_id=v_uid and role='owner' and verification_status='verified')
 then raise exception using errcode='42501',message='Verified owner required'; end if;
 return jsonb_build_object(
  'members',coalesce((select jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'verification_status',m.verification_status) order by m.created_at)
    from public.company_memberships m where m.company_id=p_company_id),'[]'::jsonb),
  'invitations',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'email',i.email,'role',i.role,'status',i.status,'expires_at',i.expires_at,'created_at',i.created_at) order by i.created_at desc)
    from public.company_access_invitations i where i.company_id=p_company_id and i.status='pending'),'[]'::jsonb)
 );
end $function$

CREATE OR REPLACE FUNCTION public.get_my_company_services(p_company_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_result jsonb;
begin
  if v_user is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select role into v_role from public.company_memberships
   where company_id=p_company_id and user_id=v_user
     and verification_status='verified' and role in ('owner','admin') limit 1;
  if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'name',s.name,'category',s.category,'description',s.description,
    'status',s.status,'created_at',s.created_at,'updated_at',s.updated_at
  ) order by s.created_at desc),'[]'::jsonb)
  into v_result
  from public.company_services s where s.company_id=p_company_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_pending_company_invitations()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_email text;
begin
 if v_uid is null then raise exception 'Authentication required'; end if;
 select lower(email) into v_email from auth.users where id=v_uid;
 update public.company_access_invitations set status='expired',updated_at=now() where status='pending' and expires_at<=now() and lower(email)=v_email;
 return coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'company_id',i.company_id,'company_name',c.name,'company_slug',c.slug,'role',i.role,'created_at',i.created_at,'expires_at',i.expires_at) order by i.created_at desc)
 from public.company_access_invitations i join public.companies c on c.id=i.company_id
 where i.status='pending' and lower(i.email)=v_email),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.get_my_specialist_publication_v1(p_specialist_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 SELECT jsonb_build_object('version',p.version,'state',coalesce(s.state,'unpublished'),'public_enabled',coalesce((SELECT enabled FROM public.specialist_public_control WHERE singleton),false),'preview',jsonb_build_object('display_name',p.display_name,'profession',p.profession,'specialization',p.specialization,'city',p.city,'description',p.description))
 INTO result FROM public.specialist_profiles p LEFT JOIN public.specialist_publication_state s ON s.specialist_id=p.id
 WHERE p.id=p_specialist_id AND p.owner_user_id=auth.uid() AND p.profile_status='draft';
 IF result IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 RETURN result;
END $function$

