CREATE OR REPLACE FUNCTION public.owner_invite_existing_company_user(p_company_id uuid, p_email text, p_role text DEFAULT 'manager'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid:=auth.uid(); v_target uuid; v_email text:=lower(btrim(p_email)); v_token text; v_hash text; v_inv uuid;
begin
 if v_owner is null then raise exception 'Authentication required'; end if;
 if p_role not in ('admin','manager','analyst') then raise exception 'Invalid role'; end if;
 if not exists(select 1 from public.company_memberships where company_id=p_company_id and user_id=v_owner and role='owner' and verification_status='verified') then raise exception 'Owner required'; end if;
 select id into v_target from auth.users where lower(email)=v_email limit 1;
 if v_target is null then return jsonb_build_object('existing_user',false); end if;
 if v_target=v_owner then raise exception 'Cannot invite yourself'; end if;
 if exists(select 1 from public.company_memberships where company_id=p_company_id and user_id=v_target) then raise exception 'User already has access to this company'; end if;
 update public.company_access_invitations set status='revoked',updated_at=now() where company_id=p_company_id and lower(email)=v_email and status='pending';
 v_token:=gen_random_uuid()::text||replace(gen_random_uuid()::text,'-','');
 v_hash:=encode(extensions.digest(v_token,'sha256'),'hex');
 insert into public.company_access_invitations(company_id,email,role,invited_by,token_hash)
 values(p_company_id,v_email,p_role,v_owner,v_hash) returning id into v_inv;
 return jsonb_build_object('existing_user',true,'invitation_id',v_inv,'token',v_token);
end $function$

CREATE OR REPLACE FUNCTION public.publish_my_specialist_details_v1(p_specialist_id uuid, p_expected_version integer, p_request_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE receipt jsonb; options jsonb; stored jsonb;
BEGIN
 IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR octet_length(p_items::text)>262144 THEN RAISE invalid_parameter_value; END IF;
 IF jsonb_array_length(p_items)>100 THEN RAISE invalid_parameter_value; END IF;
 -- Underlying v1 holds the profile lock, authorizes owner, checks CAS and performs replay handling.
 receipt:=public.publish_my_specialist_v1(p_specialist_id,p_expected_version,p_request_id);
 IF (receipt->>'replayed')::boolean THEN
  SELECT items INTO stored FROM public.specialist_revision_details_v1 WHERE specialist_id=p_specialist_id AND revision_id=(receipt->>'revision_id')::uuid;
  IF coalesce(stored,'[]')<>p_items AND (receipt->>'published')::boolean THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Selection changed'; END IF;
  RETURN receipt;
 END IF;
 options:=public.get_my_specialist_public_options_v1(p_specialist_id);
 IF EXISTS(SELECT FROM jsonb_array_elements(p_items) x WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(options) y WHERE y.value=x.value)) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Refresh publication options';
 END IF;
 INSERT INTO public.specialist_revision_details_v1 VALUES(p_specialist_id,(receipt->>'revision_id')::uuid,p_items);
 RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION public.publish_my_specialist_v1(p_specialist_id uuid, p_expected_version integer, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
DECLARE p public.specialist_profiles; s public.specialist_publication_state; previous public.specialist_publish_requests_v1; revision uuid;
BEGIN
 IF auth.uid() IS NULL OR p_request_id IS NULL OR p_expected_version IS NULL OR p_expected_version<1 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Trusted RLS-bypass owner required'; END IF;
 PERFORM 1 FROM public.specialist_public_control WHERE singleton AND enabled FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Public display disabled'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('specialist-media:'||p_specialist_id::text,0));
 SELECT * INTO p FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND OR p.profile_status<>'draft' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 INSERT INTO public.specialist_publication_state(specialist_id) VALUES(p_specialist_id) ON CONFLICT(specialist_id) DO NOTHING;
 SELECT * INTO s FROM public.specialist_publication_state WHERE specialist_id=p_specialist_id FOR UPDATE;
 IF s.state IN ('suspended','erasing') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 SELECT * INTO previous FROM public.specialist_publish_requests_v1 WHERE specialist_id=p_specialist_id AND request_id=p_request_id;
 IF FOUND THEN
  IF previous.expected_version<>p_expected_version THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Request conflict'; END IF;
  RETURN jsonb_build_object('revision_id',previous.revision_id,'source_version',previous.expected_version,'replayed',true,'published',s.state='published' AND s.published_revision_id=previous.revision_id);
 END IF;
 IF (SELECT count(*) FROM public.specialist_publish_requests_v1 WHERE specialist_id=p_specialist_id)>=1000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='Publication request limit reached'; END IF;
 IF p.version<>p_expected_version THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Version conflict'; END IF;
 PERFORM 1 FROM public.profile_slug_registry WHERE slug=p.slug AND profile_kind='specialist' AND profile_id=p.id FOR UPDATE;
 IF NOT FOUND OR position('--' IN p.slug)>0 OR EXISTS(SELECT FROM public.specialist_reserved_slugs_v1 WHERE slug=p.slug) OR EXISTS(SELECT FROM public.specialist_slug_tombstones_v1 WHERE slug=p.slug AND hold_until>pg_catalog.clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 INSERT INTO public.specialist_public_revisions(specialist_id,client_request_id,source_version,slug,display_name,profession,specialization,city,description)
 VALUES(p.id,p_request_id,p.version,p.slug,p.display_name,p.profession,p.specialization,p.city,p.description) RETURNING revision_id INTO revision;
 INSERT INTO public.specialist_publish_requests_v1(specialist_id,request_id,expected_version,revision_id) VALUES(p.id,p_request_id,p_expected_version,revision);
 UPDATE public.specialist_publication_state SET state='published',published_revision_id=revision WHERE specialist_id=p.id;
 RETURN jsonb_build_object('revision_id',revision,'source_version',p.version,'replayed',false,'published',true);
END $function$

CREATE OR REPLACE FUNCTION public.register_my_company_media(p_company_id uuid, p_storage_object_name text, p_media_type text, p_alt_text text DEFAULT NULL::text, p_caption text DEFAULT NULL::text, p_sort_order integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_media public.company_media%rowtype;
  v_expected_prefix text;
begin
  if v_uid is null then raise exception 'unauthorized' using errcode='42501'; end if;
  if p_media_type not in ('logo','cover','interior','exterior','products','team') then
    raise exception 'invalid_media_type' using errcode='22023';
  end if;
  if p_sort_order < 0 then raise exception 'invalid_sort_order' using errcode='22023'; end if;
  if not exists (
    select 1 from public.company_memberships cm
    where cm.company_id=p_company_id and cm.user_id=v_uid
      and cm.verification_status='verified' and cm.role in ('owner','admin')
  ) then raise exception 'forbidden' using errcode='42501'; end if;

  v_expected_prefix := p_company_id::text || '/' || p_media_type || '/';
  if p_storage_object_name is null or length(p_storage_object_name)>1024
     or p_storage_object_name not like v_expected_prefix || '%'
     or p_storage_object_name like '%..%' or p_storage_object_name like '%\\%'
  then raise exception 'invalid_storage_object_name' using errcode='22023'; end if;

  if not exists (
    select 1 from storage.objects so
    where so.bucket_id='company-media' and so.name=p_storage_object_name
  ) then raise exception 'storage_object_not_found' using errcode='P0002'; end if;

  update public.company_media
     set status='archived', updated_at=now()
   where company_id=p_company_id and media_type=p_media_type
     and status='published' and storage_object_name<>p_storage_object_name;

  insert into public.company_media(
    company_id,storage_object_name,media_type,status,sort_order,alt_text,caption,updated_at
  ) values (
    p_company_id,p_storage_object_name,p_media_type,'published',p_sort_order,
    nullif(btrim(p_alt_text),''),nullif(btrim(p_caption),''),now()
  )
  on conflict (company_id,storage_object_name)
  do update set media_type=excluded.media_type,status='published',
    sort_order=excluded.sort_order,alt_text=excluded.alt_text,
    caption=excluded.caption,updated_at=now()
  returning * into v_media;

  return jsonb_build_object(
    'id',v_media.id,'company_id',v_media.company_id,
    'object_name',v_media.storage_object_name,'type',v_media.media_type,
    'status',v_media.status,'sort_order',v_media.sort_order,
    'alt',v_media.alt_text,'caption',v_media.caption,'updated_at',v_media.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.register_my_specialist_media(p_specialist_id uuid, p_object_name text, p_kind text, p_caption text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.specialist_media; meta jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Authentication required'; END IF; PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() AND profile_status='draft' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 IF p_object_name IS NULL OR NOT public.can_manage_specialist_object(p_object_name) OR split_part(p_object_name,'/',1)<>p_specialist_id::text OR split_part(p_object_name,'/',2) IS DISTINCT FROM p_kind OR p_kind NOT IN ('avatar','portfolio') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid media path'; END IF;
 SELECT metadata INTO meta FROM storage.objects WHERE bucket_id='specialist-media' AND name=p_object_name;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Upload required'; END IF;
 IF coalesce((meta->>'size')::bigint,0) NOT BETWEEN 1 AND 5242880 OR coalesce(meta->>'mimetype','') NOT IN ('image/jpeg','image/png','image/webp') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid image metadata'; END IF;
 INSERT INTO public.specialist_media(specialist_id,object_name,kind,caption) VALUES(p_specialist_id,p_object_name,p_kind,nullif(btrim(p_caption),''))
 ON CONFLICT(object_name) DO UPDATE SET caption=excluded.caption RETURNING * INTO v;
 RETURN to_jsonb(v); END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_company_access_invitation(p_invitation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_company uuid;
begin
 if v_uid is null then raise exception using errcode='42501',message='Authentication required'; end if;
 select company_id into v_company from public.company_access_invitations where id=p_invitation_id and status='pending';
 if v_company is null then return false; end if;
 if not exists(select 1 from public.company_memberships where company_id=v_company and user_id=v_uid and role='owner' and verification_status='verified')
 then raise exception using errcode='42501',message='Verified owner required'; end if;
 update public.company_access_invitations set status='revoked',updated_at=now() where id=p_invitation_id and status='pending';
 return found;
end $function$

CREATE OR REPLACE FUNCTION public.save_my_specialist_channels(p_specialist_id uuid, p_version integer, p_channels jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v integer; r jsonb; normalized text; ord integer:=0; preferred integer:=0; cid uuid; lbl text; k text; flag text; allrows jsonb:='[]'; ids uuid[]:='{}'; keys text[]:='{}'; dedup text;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft not found' USING ERRCODE='42501'; END IF;
 SELECT version INTO v FROM public.specialist_channel_sets WHERE specialist_id=p_specialist_id FOR UPDATE;
 IF p_version IS NULL OR p_version<0 OR p_version<>coalesce(v,0) THEN RAISE EXCEPTION 'Contacts changed; reload' USING ERRCODE='PT409'; END IF;
 IF p_channels IS NULL OR jsonb_typeof(p_channels)<>'array' THEN RAISE EXCEPTION 'Array required' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_channels)>20 THEN RAISE EXCEPTION 'Maximum 20 contacts' USING ERRCODE='54000'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_channels) LOOP
 IF jsonb_typeof(r)<>'object' THEN RAISE EXCEPTION 'Object required' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(r) LOOP
 IF k NOT IN ('id','kind','value_raw','label','is_preferred','accepts_inquiries','is_public') THEN RAISE EXCEPTION 'Unknown field' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF jsonb_typeof(r->'id') IS DISTINCT FROM 'string' OR (r->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 OR jsonb_typeof(r->'kind') IS DISTINCT FROM 'string' OR jsonb_typeof(r->'value_raw') IS DISTINCT FROM 'string'
 OR (r ? 'label' AND jsonb_typeof(r->'label') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION 'Invalid field type' USING ERRCODE='22023'; END IF;
 FOREACH flag IN ARRAY ARRAY['is_preferred','accepts_inquiries','is_public'] LOOP
 IF r ? flag AND jsonb_typeof(r->flag) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Boolean required' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF coalesce((r->>'is_public')::boolean,false) THEN RAISE EXCEPTION 'Public contacts not enabled' USING ERRCODE='22023'; END IF;
 cid:=(r->>'id')::uuid;
 IF cid=ANY(ids) THEN RAISE EXCEPTION 'Duplicate ID' USING ERRCODE='23505'; END IF;
 IF EXISTS(SELECT 1 FROM public.specialist_contact_channels WHERE id=cid AND specialist_id<>p_specialist_id) THEN RAISE EXCEPTION 'Foreign contact' USING ERRCODE='42501'; END IF;
 ids:=array_append(ids,cid);
 normalized:=public.specialist_channel_normalize(r->>'kind',r->>'value_raw');lbl:=btrim(coalesce(r->>'label',''));
 IF char_length(lbl)>40 OR lbl ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'Invalid label' USING ERRCODE='22023'; END IF;
 dedup:=(r->>'kind')||'|'||normalized;
 IF dedup=ANY(keys) THEN RAISE EXCEPTION 'Duplicate contact' USING ERRCODE='23505'; END IF;
 keys:=array_append(keys,dedup);
 IF coalesce((r->>'is_preferred')::boolean,false) THEN preferred:=preferred+1;END IF;
 IF preferred>1 THEN RAISE EXCEPTION 'One preferred contact only' USING ERRCODE='22023'; END IF;
 allrows:=allrows||jsonb_build_array(jsonb_build_object('id',cid,'kind',r->>'kind','value_raw',r->>'value_raw','href',normalized,'label',lbl,'sort_order',ord,'is_preferred',coalesce((r->>'is_preferred')::boolean,false),'accepts_inquiries',coalesce((r->>'accepts_inquiries')::boolean,false),'is_public',false));ord:=ord+1;
 END LOOP;
 INSERT INTO public.specialist_channel_sets(specialist_id,version) VALUES(p_specialist_id,1) ON CONFLICT(specialist_id) DO UPDATE SET version=public.specialist_channel_sets.version+1,updated_at=now();
 DELETE FROM public.specialist_contact_channels WHERE specialist_id=p_specialist_id;
 INSERT INTO public.specialist_contact_channels SELECT x.id,p_specialist_id,x.kind,x.value_raw,x.href,x.label,x.sort_order,x.is_preferred,x.accepts_inquiries,x.is_public
 FROM jsonb_to_recordset(allrows) AS x(id uuid,kind text,value_raw text,href text,label text,sort_order integer,is_preferred boolean,accepts_inquiries boolean,is_public boolean);
 RETURN public.list_my_specialist_channels(p_specialist_id);
END $function$

