CREATE OR REPLACE FUNCTION public.specialist_channel_normalize(p_kind text, p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE s text:=btrim(p_value); m text[]; host text; path text; q text; segment text;
BEGIN
 IF p_kind IS NULL OR p_kind NOT IN ('telegram','max','vk','whatsapp','ok','website','portfolio')
 OR s IS NULL OR s='' OR char_length(s)>500 OR s ~ '[^!-~]' OR s ~ $r$[\\<>"']$r$
 OR s ~* '%(0[0-9a-f]|1[0-9a-f]|7f|5c|3c|3e|22|27)' THEN RAISE EXCEPTION 'Invalid contact' USING ERRCODE='22023'; END IF;
 IF p_kind='telegram' AND s ~ '^@[A-Za-z][A-Za-z0-9_]{0,31}$' THEN s:='https://t.me/'||substr(s,2); END IF;
 IF p_kind='whatsapp' AND s ~ '^\+[1-9][0-9]{7,14}$' THEN s:='https://wa.me/'||ltrim(s,'+'); END IF;
 m:=regexp_match(s,'^https://([^/?#]+)([^?#]*)(\?[^#]*)?$');
 IF s ~* '%([^0-9a-f]|[0-9a-f]([^0-9a-f]|$)|$)' OR s ~* '(/|%2f)(\.|%2e){1,2}(/|%2f|\?|$)' THEN RAISE EXCEPTION 'Invalid URL path' USING ERRCODE='22023'; END IF;
 IF m IS NULL THEN RAISE EXCEPTION 'HTTPS URL required' USING ERRCODE='22023'; END IF;
 host:=lower(m[1]);path:=coalesce(nullif(m[2],''),'/');q:=coalesce(m[3],'');
 IF char_length(host)>253 OR host !~ '\.[a-z]{2,63}$' OR host ~ '\.(local|localhost|internal|invalid|test|example)$' THEN RAISE EXCEPTION 'Invalid host' USING ERRCODE='22023'; END IF;
 FOREACH segment IN ARRAY string_to_array(host,'.') LOOP
 IF segment !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$' OR segment LIKE 'xn--%' THEN RAISE EXCEPTION 'Invalid host label' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF p_kind='telegram' THEN
 IF host NOT IN ('t.me','telegram.me') OR path !~ '^/[A-Za-z][A-Za-z0-9_]{0,31}/?$' OR q<>'' OR replace(path,'/','') ~* '^(share|proxy|socks|login|joinchat|addstickers|addemoji|boost|giftcode|invoice|iv|c|s|bg|contact|confirmphone|setlanguage)$' THEN RAISE EXCEPTION 'Invalid Telegram profile' USING ERRCODE='22023';END IF;
 host:='t.me';path:='/'||lower(replace(path,'/',''));
 ELSIF p_kind='whatsapp' THEN
 IF host<>'wa.me' OR path !~ '^/[1-9][0-9]{7,14}$' OR q<>'' THEN RAISE EXCEPTION 'Invalid WhatsApp number' USING ERRCODE='22023'; END IF;
 ELSIF p_kind='vk' THEN
 IF host NOT IN ('vk.com','m.vk.com') OR path !~ '^/[A-Za-z0-9_.-]+/?$' OR q<>'' OR path ~* '^/(away(\.php)?|login|oauth|share|cc)/?$' THEN RAISE EXCEPTION 'Invalid VK profile' USING ERRCODE='22023'; END IF;
 host:='vk.com';path:=lower(rtrim(path,'/'));
 ELSIF p_kind='ok' THEN
 IF host NOT IN ('ok.ru','m.ok.ru') OR path !~ '^/(profile/[0-9]+|[A-Za-z0-9_.-]+)/?$' OR q<>'' OR path ~* '^/(dk|login|help|outlink|away)/?$' THEN RAISE EXCEPTION 'Invalid OK profile' USING ERRCODE='22023'; END IF;
 host:='ok.ru';path:=lower(rtrim(path,'/'));
 ELSIF p_kind='max' THEN
 IF host<>'max.ru' OR path='/' OR q<>'' THEN RAISE EXCEPTION 'Copied MAX profile URL required' USING ERRCODE='22023'; END IF;
 END IF;
 RETURN 'https://'||host||path||q;
END $function$

CREATE OR REPLACE FUNCTION public.specialist_disable_public_v1(p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '2s'
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT FROM public.specialist_operator_identities WHERE user_id=auth.uid() AND enabled) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Registered operator required'; END IF;
 IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Reason required'; END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Trusted RLS-bypass owner required'; END IF;
 UPDATE public.specialist_public_control SET enabled=false WHERE singleton AND enabled;
 IF FOUND THEN INSERT INTO public.specialist_public_operator_audit_v1(actor,action,reason) VALUES(auth.uid(),'disable_projection',p_reason); END IF;
 RETURN jsonb_build_object('enabled',false);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_gateway_begin_delete(p_owner uuid, p_specialist_id uuid, p_object_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_upload_reservations; kind text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=p_owner AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 IF NOT (SELECT deletions_enabled FROM public.specialist_upload_control WHERE singleton) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Media deletion disabled'; END IF;
 IF p_object_name IS NULL OR split_part(p_object_name,'/',1)<>p_specialist_id::text OR p_object_name !~ '^[0-9a-f-]{36}/(avatar|portfolio)/[0-9a-f-]{36}[.](png|jpg|jpeg|webp)$' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Object unavailable'; END IF;
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE object_name=p_object_name FOR UPDATE;
 IF FOUND THEN
  IF r.state='uploading' THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Unknown in-flight upload; retain reservation'; END IF;
  IF r.state='deleted' THEN RETURN to_jsonb(r); END IF;
  UPDATE public.specialist_upload_reservations SET state='deleting' WHERE id=r.id RETURNING * INTO r;
 ELSE
  IF NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=p_object_name) AND NOT EXISTS(SELECT FROM public.specialist_media WHERE specialist_id=p_specialist_id AND object_name=p_object_name) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Object unavailable'; END IF;
  kind:=split_part(p_object_name,'/',2);
  INSERT INTO public.specialist_upload_reservations(id,profile_id,specialist_id,object_name,kind,state) VALUES(gen_random_uuid(),p_specialist_id,p_specialist_id,p_object_name,kind,'deleting') RETURNING * INTO r;
 END IF;
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_gateway_finish(p_owner uuid, p_specialist_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_upload_reservations; v public.specialist_media; meta jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=p_owner AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE id=p_request_id AND specialist_id=p_specialist_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Upload unavailable'; END IF;
 IF r.state NOT IN ('uploading','ready') THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Upload retired'; END IF;
 SELECT metadata INTO meta FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name;
 IF NOT FOUND OR (meta->>'size')::bigint IS DISTINCT FROM r.size_bytes OR meta->>'mimetype' IS DISTINCT FROM r.mime THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Upload pending or metadata mismatch; reservation retained'; END IF;
 INSERT INTO public.specialist_media(specialist_id,object_name,kind,caption) VALUES(p_specialist_id,r.object_name,r.kind,r.caption) ON CONFLICT(object_name) DO UPDATE SET caption=excluded.caption RETURNING * INTO v;
 UPDATE public.specialist_upload_reservations SET state='ready' WHERE id=r.id;
 RETURN to_jsonb(v);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_gateway_finish_delete(p_owner uuid, p_specialist_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_upload_reservations;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=p_owner AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE id=p_request_id AND profile_id=p_specialist_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Object unavailable'; END IF;
 IF r.state NOT IN ('deleting','deleted') OR EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Storage deletion not confirmed'; END IF;
 DELETE FROM public.specialist_media WHERE specialist_id=p_specialist_id AND object_name=r.object_name;
 UPDATE public.specialist_upload_reservations SET state='deleted',specialist_id=NULL,fingerprint=NULL,mime=NULL,size_bytes=NULL,caption=NULL WHERE id=r.id;
 RETURN jsonb_build_object('deleted',true);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_gateway_force_retire(p_owner uuid, p_specialist_id uuid, p_request_id uuid, p_phase text, p_actor text, p_reason text, p_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_upload_reservations;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=p_owner AND profile_status IN ('draft','erasing') FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 IF (SELECT enabled FROM public.specialist_upload_control WHERE singleton) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Disable upload admission before operator retirement'; END IF;
 IF p_phase IS NULL OR p_phase NOT IN ('begin','finish') OR p_reason IS NULL OR char_length(p_reason) NOT BETWEEN 3 AND 500 OR p_proof IS NULL OR jsonb_typeof(p_proof)<>'object' OR octet_length(p_proof::text)>8192
 OR (p_proof->>'kind') IS NULL OR (p_proof->>'kind') NOT IN ('provider_terminal_no_late_writer','credentials_revoked_all_writers_drained')
 OR coalesce(char_length(p_proof->>'evidence_ref'),0) NOT BETWEEN 8 AND 1000
 OR (p_proof->>'request_id') IS DISTINCT FROM p_request_id::text
 OR p_proof->'all_writers_stopped' IS DISTINCT FROM 'true'::jsonb THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Reviewed external no-late-writer evidence required; TTL is not proof';
 END IF;
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE id=p_request_id AND profile_id=p_specialist_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Upload unavailable'; END IF;
 IF coalesce(p_proof->>'authorization_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR coalesce(p_proof->>'mode','') NOT IN ('quarantine_retire','confirmed_erasure') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Explicit authorized erasure mode required'; END IF;
 IF (r.state='ready' OR EXISTS(SELECT FROM public.specialist_media WHERE object_name=r.object_name)) AND p_proof->>'mode' IS DISTINCT FROM 'confirmed_erasure' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Ready media requires confirmed erasure mode'; END IF;
 p_actor:=public.specialist_operator_check((p_proof->>'authorization_id')::uuid,p_specialist_id,p_request_id,'profile_erasure',EXISTS(SELECT FROM public.specialist_upload_audit a WHERE a.request_id=r.id AND a.action='operator_begin' AND a.evidence=p_proof AND a.actor=auth.uid()::text AND (p_phase='finish' OR NOT EXISTS(SELECT FROM public.specialist_upload_audit z WHERE z.request_id=r.id AND z.action='operator_finish' AND z.evidence=p_proof AND z.actor=a.actor AND z.created_at>=a.created_at))))::text;
 IF r.state='deleted' AND NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name) THEN RETURN jsonb_build_object('retired',true,'object_name',r.object_name); END IF;
 IF p_phase='begin' THEN
  INSERT INTO public.specialist_upload_audit(request_id,profile_id,action,actor,reason,evidence) VALUES(r.id,p_specialist_id,'operator_begin',p_actor,p_reason,p_proof);
  UPDATE public.specialist_upload_reservations SET state='deleting',specialist_id=p_specialist_id WHERE id=r.id;
  RETURN jsonb_build_object('retired',false,'object_name',r.object_name);
 END IF;
 IF r.state<>'deleting' OR NOT EXISTS(SELECT FROM public.specialist_upload_audit WHERE request_id=r.id AND action='operator_begin' AND evidence=p_proof AND actor=p_actor) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Audited begin with same proof required'; END IF;
 IF EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Remove object through Storage API first'; END IF;
 DELETE FROM public.specialist_media WHERE specialist_id=p_specialist_id AND object_name=r.object_name;
 INSERT INTO public.specialist_upload_audit(request_id,profile_id,action,actor,reason,evidence) VALUES(r.id,p_specialist_id,'operator_finish',p_actor,p_reason,p_proof);
 UPDATE public.specialist_upload_reservations SET state='deleted',specialist_id=NULL,fingerprint=NULL,mime=NULL,size_bytes=NULL,caption=NULL WHERE id=r.id;
 RETURN jsonb_build_object('retired',true,'object_name',r.object_name);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_gateway_reject(p_owner uuid, p_specialist_id uuid, p_request_id uuid, p_http_status integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_upload_reservations;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=p_owner AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 IF p_http_status IS NULL OR p_http_status<400 OR p_http_status>=500 OR p_http_status IN (408,409) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Not a definite Storage rejection'; END IF;
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE id=p_request_id AND profile_id=p_specialist_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Upload unavailable'; END IF;
 IF r.state='deleted' THEN RETURN jsonb_build_object('retired',true); END IF;
 IF r.state<>'uploading' OR EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Object or nonpending request; retain reservation'; END IF;
 INSERT INTO public.specialist_upload_audit(request_id,profile_id,action,actor,reason,evidence) VALUES(r.id,p_specialist_id,'definite_rejection','gateway','Storage returned terminal non-timeout non-conflict 4xx',jsonb_build_object('http_status',p_http_status,'one_attempt',true));
 UPDATE public.specialist_upload_reservations SET state='deleted',specialist_id=NULL,fingerprint=NULL,mime=NULL,size_bytes=NULL,caption=NULL WHERE id=r.id;
 RETURN jsonb_build_object('retired',true);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_gateway_reserve(p_owner uuid, p_specialist_id uuid, p_request_id uuid, p_kind text, p_fingerprint text, p_mime text, p_size integer, p_caption text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_upload_reservations; n integer; path text; ext text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=p_owner AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 IF NOT (SELECT enabled FROM public.specialist_upload_control WHERE singleton) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Uploads disabled'; END IF;
 IF p_request_id IS NULL OR p_kind NOT IN ('avatar','portfolio') OR p_kind IS NULL OR p_fingerprint !~ '^[a-f0-9]{64}$' OR p_fingerprint IS NULL OR p_mime NOT IN ('image/png','image/jpeg','image/webp') OR p_mime IS NULL OR p_size NOT BETWEEN 1 AND 5242880 OR p_size IS NULL OR char_length(coalesce(p_caption,''))>500 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid upload'; END IF;
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE id=p_request_id;
 IF FOUND THEN
  IF r.profile_id<>p_specialist_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Upload unavailable'; END IF;
  IF r.state='deleted' THEN RETURN to_jsonb(r)||jsonb_build_object('upload_allowed',false); END IF;
  IF r.fingerprint IS DISTINCT FROM p_fingerprint OR r.kind<>p_kind OR r.caption IS DISTINCT FROM p_caption THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Request changed'; END IF;
  RETURN to_jsonb(r)||jsonb_build_object('upload_allowed',false);
 END IF;
 SELECT count(*)::int INTO n FROM storage.objects WHERE bucket_id='specialist-media' AND split_part(name,'/',1)=p_specialist_id::text;
 n:=n+(SELECT count(*)::int FROM public.specialist_upload_reservations u WHERE u.specialist_id=p_specialist_id AND u.state<>'deleted' AND NOT EXISTS(SELECT FROM storage.objects o WHERE o.bucket_id='specialist-media' AND o.name=u.object_name));
 IF n>=20 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='Upload limit reached'; END IF;
 IF p_kind='avatar' AND (EXISTS(SELECT FROM public.specialist_media WHERE specialist_id=p_specialist_id AND kind='avatar') OR EXISTS(SELECT FROM public.specialist_upload_reservations WHERE specialist_id=p_specialist_id AND kind='avatar' AND state<>'deleted')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Avatar already exists'; END IF;
 ext:=CASE p_mime WHEN 'image/png' THEN 'png' WHEN 'image/jpeg' THEN 'jpg' ELSE 'webp' END;
 path:=p_specialist_id::text||'/'||p_kind||'/'||p_request_id::text||'.'||ext;
 IF EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=path) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Object already exists'; END IF;
 INSERT INTO public.specialist_upload_reservations(id,profile_id,specialist_id,object_name,kind,fingerprint,mime,size_bytes,caption,state) VALUES(p_request_id,p_specialist_id,p_specialist_id,path,p_kind,p_fingerprint,p_mime,p_size,p_caption,'uploading') RETURNING * INTO r;
 RETURN to_jsonb(r)||jsonb_build_object('upload_allowed',true);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_operator_authorize(p_specialist_id uuid, p_confirmation_id uuid, p_request_id uuid, p_purpose text, p_ticket text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_result public.specialist_erasure_authorizations; deadline timestamptz;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT FROM public.specialist_operator_identities WHERE user_id=auth.uid() AND enabled) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Registered operator required'; END IF;
 IF p_ticket IS NULL OR p_ticket !~ '^OTZ-[A-Z0-9-]{8,100}$' OR p_purpose IS NULL OR p_purpose NOT IN ('profile_erasure','orphan_cleanup') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid reviewed authorization'; END IF;
 IF p_purpose='profile_erasure' THEN
  SELECT c.expires_at INTO deadline FROM public.specialist_erasure_confirmations c JOIN public.specialist_profiles p ON p.id=c.profile_id AND p.owner_user_id=c.owner_user_id AND p.profile_status IN ('draft','erasing') WHERE c.id=p_confirmation_id AND c.profile_id=p_specialist_id AND c.expires_at>now();
  IF NOT FOUND OR p_request_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Live owner confirmation required'; END IF;
 ELSE
  IF p_confirmation_id IS NOT NULL OR EXISTS(SELECT FROM public.specialist_profiles WHERE id=p_specialist_id) OR NOT EXISTS(SELECT FROM public.specialist_upload_reservations r WHERE r.id=p_request_id AND r.profile_id=p_specialist_id AND r.state='deleted' AND r.specialist_id IS NULL AND EXISTS(SELECT FROM public.specialist_upload_audit a WHERE a.request_id=r.id AND a.profile_id=r.profile_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Audited deleted-profile tombstone required'; END IF;
  deadline:=now()+interval '15 minutes';
 END IF;
 INSERT INTO public.specialist_erasure_authorizations(profile_id,request_id,purpose,approved_by,confirmation_id,ticket,expires_at) VALUES(p_specialist_id,p_request_id,p_purpose,auth.uid(),p_confirmation_id,p_ticket,deadline) RETURNING * INTO v_result;
 RETURN jsonb_build_object('authorization_id',v_result.id,'approved_by',v_result.approved_by,'expires_at',v_result.expires_at);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_operator_cleanup_orphan(p_request_id uuid, p_phase text, p_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.specialist_upload_reservations; v_actor uuid; resumed boolean; completed boolean;
BEGIN
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE id=p_request_id;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Tombstone unavailable'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||r.profile_id::text,0));
 SELECT * INTO r FROM public.specialist_upload_reservations WHERE id=p_request_id FOR UPDATE;
 IF EXISTS(SELECT FROM public.specialist_profiles WHERE id=r.profile_id) OR r.state<>'deleted' OR r.specialist_id IS NOT NULL OR NOT EXISTS(SELECT FROM public.specialist_upload_audit WHERE request_id=r.id AND profile_id=r.profile_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Audited deleted-profile tombstone required'; END IF;
 IF (SELECT enabled FROM public.specialist_upload_control WHERE singleton) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Disable admission first'; END IF;
 IF p_phase IS NULL OR p_phase NOT IN ('begin','finish') OR p_proof IS NULL OR jsonb_typeof(p_proof)<>'object' OR octet_length(p_proof::text)>8192 OR p_proof->>'mode' IS DISTINCT FROM 'orphan_cleanup' OR p_proof->>'request_id' IS DISTINCT FROM r.id::text OR p_proof->'all_writers_stopped' IS DISTINCT FROM 'true'::jsonb OR coalesce(p_proof->>'kind','') NOT IN ('provider_terminal_no_late_writer','credentials_revoked_all_writers_drained') OR coalesce(char_length(p_proof->>'evidence_ref'),0) NOT BETWEEN 8 AND 1000 OR coalesce(p_proof->>'authorization_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Reviewed writer-stop evidence required'; END IF;
 completed:=EXISTS(SELECT FROM public.specialist_upload_audit WHERE request_id=r.id AND action='orphan_finish' AND evidence=p_proof AND actor=auth.uid()::text);
 resumed:=EXISTS(SELECT FROM public.specialist_upload_audit a WHERE a.request_id=r.id AND a.action='orphan_begin' AND a.evidence=p_proof AND a.actor=auth.uid()::text AND (p_phase='finish' OR NOT EXISTS(SELECT FROM public.specialist_upload_audit z WHERE z.request_id=r.id AND z.action='orphan_finish' AND z.evidence=p_proof AND z.actor=a.actor AND z.created_at>=a.created_at)));
 -- Serialize all uses of this authorization, including different proof values.
 PERFORM 1 FROM public.specialist_erasure_authorizations WHERE id=(p_proof->>'authorization_id')::uuid FOR UPDATE;
 v_actor:=public.specialist_operator_check((p_proof->>'authorization_id')::uuid,r.profile_id,r.id,'orphan_cleanup',resumed OR (completed AND NOT EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name)));
 IF p_phase='begin' AND NOT completed THEN
  IF resumed THEN
   IF NOT EXISTS(SELECT FROM public.specialist_erasure_authorizations WHERE id=(p_proof->>'authorization_id')::uuid AND expires_at>clock_timestamp()) OR NOT EXISTS(SELECT FROM public.specialist_upload_audit WHERE request_id=r.id AND action='orphan_begin' AND evidence=p_proof AND actor=v_actor::text AND created_at>clock_timestamp()-interval '15 minutes') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Begin expired; fresh authorization required'; END IF;
   RETURN jsonb_build_object('deleted',false,'object_name',r.object_name);
  END IF;
  IF EXISTS(SELECT FROM public.specialist_upload_audit WHERE action='orphan_begin' AND evidence->>'authorization_id'=p_proof->>'authorization_id') THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Authorization already consumed'; END IF;
 END IF;
 IF p_phase='begin' AND completed THEN
  IF EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='New late object needs fresh authorization and proof'; END IF;
  RETURN jsonb_build_object('deleted',true,'object_name',r.object_name);
 END IF;
 IF p_phase='finish' THEN
  IF NOT resumed OR EXISTS(SELECT FROM storage.objects WHERE bucket_id='specialist-media' AND name=r.object_name) THEN RAISE EXCEPTION USING ERRCODE='PT409',MESSAGE='Audited begin and Storage deletion required'; END IF;
  IF EXISTS(SELECT FROM public.specialist_upload_audit WHERE request_id=r.id AND action='orphan_finish' AND evidence=p_proof AND actor=v_actor::text) THEN RETURN jsonb_build_object('deleted',true); END IF;
 END IF;
 INSERT INTO public.specialist_upload_audit(request_id,profile_id,action,actor,reason,evidence) VALUES(r.id,r.profile_id,CASE p_phase WHEN 'begin' THEN 'orphan_begin' ELSE 'orphan_finish' END,v_actor::text,'Authorized deleted-profile orphan cleanup',p_proof);
 RETURN jsonb_build_object('deleted',p_phase='finish','object_name',r.object_name);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_operator_plan_erasure(p_owner uuid, p_specialist_id uuid, p_authorization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o record;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=p_owner AND profile_status IN ('draft','erasing') FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft unavailable'; END IF;
 PERFORM public.specialist_operator_check(p_authorization_id,p_specialist_id,NULL,'profile_erasure');
 IF (SELECT enabled FROM public.specialist_upload_control WHERE singleton) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Disable admission first'; END IF;
 FOR o IN SELECT name FROM storage.objects WHERE bucket_id='specialist-media' AND split_part(name,'/',1)=p_specialist_id::text LOOP
  IF o.name !~ '^[0-9a-f-]{36}/(avatar|portfolio)/[0-9a-f-]{36}[.](png|jpg|jpeg|webp)$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Unexpected legacy path requires review'; END IF;
  INSERT INTO public.specialist_upload_reservations(id,profile_id,specialist_id,object_name,kind,state) SELECT gen_random_uuid(),p_specialist_id,p_specialist_id,o.name,split_part(o.name,'/',2),'ready' WHERE NOT EXISTS(SELECT FROM public.specialist_upload_reservations WHERE object_name=o.name);
 END LOOP;
 RETURN public.specialist_gateway_erasure_inventory(p_owner,p_specialist_id)||jsonb_build_object('planned',true,'authorization_id',p_authorization_id);
END $function$

CREATE OR REPLACE FUNCTION public.specialist_revision_insert_lock_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Trusted RLS-bypass owner required';
 END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('specialist-media:'||NEW.specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=NEW.specialist_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Specialist unavailable'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.specialist_slug_quarantine_purge_v1()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE removed bigint;
BEGIN
 DELETE FROM public.specialist_slug_tombstones_v1 WHERE hold_until<=pg_catalog.clock_timestamp();
 GET DIAGNOSTICS removed = ROW_COUNT;
 RETURN removed;
END
$function$

CREATE OR REPLACE FUNCTION public.specialist_slug_quarantine_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old_slug text; new_slug text;
BEGIN
 IF TG_OP <> 'INSERT' THEN old_slug := OLD.slug; END IF;
 IF TG_OP <> 'DELETE' THEN new_slug := NEW.slug; END IF;
 -- Lock both names in lexical order on a rename to avoid opposite-order deadlocks.
 IF old_slug IS NOT NULL AND new_slug IS NOT NULL AND old_slug <> new_slug THEN
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('otzovik-slug:' || least(old_slug,new_slug),0));
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('otzovik-slug:' || greatest(old_slug,new_slug),0));
 ELSE
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('otzovik-slug:' || coalesce(old_slug,new_slug),0));
 END IF;
 IF new_slug IS NOT NULL AND (TG_OP = 'INSERT' OR new_slug IS DISTINCT FROM old_slug) THEN
  DELETE FROM public.specialist_slug_tombstones_v1 WHERE slug=new_slug AND hold_until<=pg_catalog.clock_timestamp();
  IF EXISTS(SELECT 1 FROM public.specialist_slug_tombstones_v1 WHERE slug=new_slug) THEN
   RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='Slug unavailable';
  END IF;
 END IF;
 IF TG_ARGV[0]='specialist' AND old_slug IS NOT NULL AND (TG_OP='DELETE' OR old_slug IS DISTINCT FROM new_slug) THEN
  INSERT INTO public.specialist_slug_tombstones_v1(slug,hold_until)
  VALUES(old_slug,pg_catalog.clock_timestamp()+interval '90 days')
  ON CONFLICT(slug) DO UPDATE SET hold_until=greatest(public.specialist_slug_tombstones_v1.hold_until,EXCLUDED.hold_until);
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END
$function$

CREATE OR REPLACE FUNCTION public.specialist_suspend_public_v1(p_specialist_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s public.specialist_publication_state;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT FROM public.specialist_operator_identities WHERE user_id=auth.uid() AND enabled) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Registered operator required'; END IF;
 IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Reason required'; END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Trusted RLS-bypass owner required'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 INSERT INTO public.specialist_publication_state(specialist_id) VALUES(p_specialist_id) ON CONFLICT(specialist_id) DO NOTHING;
 SELECT * INTO s FROM public.specialist_publication_state WHERE specialist_id=p_specialist_id FOR UPDATE;
 IF s.state='erasing' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 IF s.state<>'suspended' THEN
  UPDATE public.specialist_publication_state SET state='suspended',published_revision_id=NULL WHERE specialist_id=p_specialist_id;
  INSERT INTO public.specialist_public_operator_audit_v1(specialist_id,actor,action,reason) VALUES(p_specialist_id,auth.uid(),'suspend',p_reason);
 END IF;
 RETURN jsonb_build_object('suspended',true);
END $function$

CREATE OR REPLACE FUNCTION public.sync_profile_slug_registry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_kind text := TG_ARGV[0];
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.slug IS NOT DISTINCT FROM OLD.slug THEN
    RETURN NEW;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    IF NEW.slug <> lower(btrim(NEW.slug))
       OR NEW.slug !~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$'
       OR NEW.slug IN ('www','api','admin','test','test2','account','login','profiles','specialists') THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid or reserved slug';
    END IF;
    INSERT INTO public.profile_slug_registry(slug,profile_kind,profile_id)
    VALUES (NEW.slug,v_kind,NEW.id);
  END IF;
  IF TG_OP <> 'INSERT' THEN
    DELETE FROM public.profile_slug_registry
    WHERE slug=lower(btrim(OLD.slug)) AND profile_kind=v_kind AND profile_id=OLD.id;
  END IF;
  RETURN NULL; -- AFTER trigger return value is ignored
END
$function$

CREATE OR REPLACE FUNCTION public.unpublish_my_specialist_v1(p_specialist_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s public.specialist_publication_state;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Trusted RLS-bypass owner required'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('specialist-media:'||p_specialist_id::text,0));
 PERFORM 1 FROM public.specialist_profiles WHERE id=p_specialist_id AND owner_user_id=auth.uid() AND profile_status='draft' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 INSERT INTO public.specialist_publication_state(specialist_id) VALUES(p_specialist_id) ON CONFLICT(specialist_id) DO NOTHING;
 SELECT * INTO s FROM public.specialist_publication_state WHERE specialist_id=p_specialist_id FOR UPDATE;
 IF s.state IN ('suspended','erasing') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Specialist unavailable'; END IF;
 UPDATE public.specialist_publication_state SET state='unpublished',published_revision_id=NULL WHERE specialist_id=p_specialist_id;
 RETURN jsonb_build_object('published',false);
END $function$

CREATE OR REPLACE FUNCTION public.update_my_company_profile(p_company_id uuid, p_name text, p_description text DEFAULT NULL::text, p_website text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare v_user_id uuid := auth.uid(); v_role text; v_old jsonb; v_new jsonb;
begin
 if v_user_id is null then raise exception 'authentication_required' using errcode='42501'; end if;
 if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'name_required' using errcode='22023'; end if;
 if char_length(trim(p_name))>200 then raise exception 'name_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_description,''))>2000 then raise exception 'description_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_website,''))>500 then raise exception 'website_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_phone,''))>100 then raise exception 'phone_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_city,''))>120 then raise exception 'city_too_long' using errcode='22023'; end if;
 if char_length(coalesce(p_email,''))>320 then raise exception 'email_too_long' using errcode='22023'; end if;
 select cm.role into v_role from public.company_memberships cm join public.companies c on c.id=cm.company_id and c.status='active'
 where cm.user_id=v_user_id and cm.company_id=p_company_id and cm.verification_status='verified' and cm.role in ('owner','admin') limit 1;
 if v_role is null then raise exception 'verified_owner_or_admin_required' using errcode='42501'; end if;
 select jsonb_build_object('name',c.name,'description',c.description,'website',c.website,'phone',c.phone,'city',c.city,'email',c.email)
 into v_old from public.companies c where c.id=p_company_id for update;
 update public.companies set name=trim(p_name),description=nullif(trim(coalesce(p_description,'')),''),
 website=nullif(trim(coalesce(p_website,'')),''),phone=nullif(trim(coalesce(p_phone,'')),''),
 city=nullif(trim(coalesce(p_city,'')),''),email=nullif(trim(coalesce(p_email,'')),''),
 updated_at=now() where id=p_company_id;
 select jsonb_build_object('id',c.id,'slug',c.slug,'name',c.name,'description',c.description,'website',c.website,'phone',c.phone,'city',c.city,'email',c.email,'status',c.status,'profile_status',c.profile_status)
 into v_new from public.companies c where c.id=p_company_id;
 insert into public.audit_log(company_id,user_id,action,target_type,target_id,metadata)
 values(p_company_id,v_user_id,'company_profile.updated','company',p_company_id::text,jsonb_build_object('role',v_role,'before',v_old,'after',v_new));
 return jsonb_build_object('company_id',p_company_id,'role',v_role,'company',v_new);
end; $function$

CREATE OR REPLACE FUNCTION public.update_my_specialist_draft(p_id uuid, p_display_name text, p_profession text, p_specialization text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_uid uuid := auth.uid(); v_id uuid;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Authentication required'; END IF;
 IF char_length(btrim(coalesce(p_display_name,''))) NOT BETWEEN 2 AND 150 OR char_length(btrim(coalesce(p_profession,''))) NOT BETWEEN 1 AND 120 OR char_length(coalesce(p_specialization,'')) > 160 OR char_length(coalesce(p_city,'')) > 120 OR char_length(coalesce(p_description,'')) > 2000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid fields'; END IF;
 UPDATE public.specialist_profiles SET display_name=btrim(p_display_name),profession=nullif(btrim(coalesce(p_profession,'')),''),specialization=nullif(btrim(coalesce(p_specialization,'')),''),city=nullif(btrim(coalesce(p_city,'')),''),description=nullif(btrim(coalesce(p_description,'')),''),updated_at=now() WHERE id=p_id AND owner_user_id=v_uid AND profile_status='draft' RETURNING id INTO v_id;
 IF v_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Draft not found or access denied'; END IF;
 RETURN jsonb_build_object('id',v_id,'profile_status','draft');
END
$function$
